sys_script_include.script:
var IllumioDeletionHandler = Class.create();
IllumioDeletionHandler.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    deleteSelectedWorkloads: function() {
        var checkedSysIds = String(this.getParameter('sysparm_checked_sysids') || '');
        var result = { success: false, message: '' };

        try {
            if (gs.nil(checkedSysIds)) {
                result.message = 'No workloads selected.';
                return JSON.stringify(result);
            }

            var sysIds = checkedSysIds ? checkedSysIds.split(',').filter(Boolean) : [];
            var utils = new IllumioUtils();
            var payload = utils.buildDeletionPayloadFromSysIds(sysIds);

            if (!payload.success) {
                result.message = payload.message;
                return JSON.stringify(result);
            }

            if (payload.deletionCount === 0 && payload.unpairCount === 0) {
                result.message = 'None of the selected workloads are eligible for deletion (not known to PCE or missing href).';
                return JSON.stringify(result);
            }

            var configSet = {};
            for (var i = 0; i < sysIds.length; i++) {
                var wlGr = new GlideRecord('x_illu2_illumio_illumio_pce_workload');
                if (wlGr.get(sysIds[i])) {
                    var cfg = wlGr.getValue('illumio_pce_configuration');
                    if (!gs.nil(cfg)) {
                        configSet[cfg] = true;
                    }
                }
            }
            var configKeys = Object.keys(configSet);
            if (configKeys.length > 1) {
                result.message = 'Selected workloads belong to multiple PCE Configurations. Please select workloads from a single configuration.';
                return JSON.stringify(result);
            }
            if (configKeys.length === 0) {
                result.message = 'Could not determine PCE Configuration for the selected workloads.';
                return JSON.stringify(result);
            }
            var configSysId = configKeys[0];

            var runningJobs = new GlideAggregate('x_illu2_illumio_illumio_scheduled_jobs');
            runningJobs.addQuery('job_status', 'running');
            runningJobs.addQuery('illumio_pce_configuration', configSysId);
            runningJobs.addAggregate('COUNT');
            runningJobs.query();
            if (runningJobs.next() && parseInt(runningJobs.getAggregate('COUNT')) > 0) {
                result.message = 'Another job is already running for this PCE Configuration. Please wait for it to complete.';
                return JSON.stringify(result);
            }

            var scheduledJobGr = new GlideRecordSecure('x_illu2_illumio_illumio_scheduled_jobs');
            scheduledJobGr.initialize();
            scheduledJobGr.job_owner = gs.getUser().getID();
            scheduledJobGr.job_type = 'deletion';
            scheduledJobGr.job_status = 'running';
            scheduledJobGr.job_started = new GlideDateTime();
            scheduledJobGr.current_operation = 'Deleting selected workloads';
            scheduledJobGr.illumio_pce_configuration = configSysId;

            var logTimestamp = new Date(new GlideDateTime().getNumericValue()).toISOString();
            var logs = '[' + logTimestamp + '] Manual deletion started: ' + payload.deletionCount + ' workload(s) for deletion, ' + payload.unpairCount + ' workload(s) for unpair';
            if (payload.skippedCount > 0) {
                logs += ', ' + payload.skippedCount + ' skipped';
            }
            scheduledJobGr.logs = logs;
            var jobSysId = scheduledJobGr.insert();

            if (gs.nil(jobSysId)) {
                result.message = 'Failed to create scheduled job for deletion.';
                return JSON.stringify(result);
            }

            var pceConfig = new IllumioGetPCEConfiguration().getConfiguration(configSysId);

            var parameters = {
                jobSysId: jobSysId,
                operation: 'delete',
                partialSucc: 'false',
                skipped: payload.skippedCount + '',
                workloads_to_delete: JSON.stringify(payload.retiredWorkloads),
                vens_to_unpair: JSON.stringify(payload.vensToUnpair),
                pce_url: pceConfig.pceUrl,
                pce_secret: pceConfig.pceSecret,
                pce_username: pceConfig.pceUsername,
                pce_org_id: pceConfig.pceOrganizationID + '',
                pce_authorization: gs.base64Encode(pceConfig.pceUsername + ':' + pceConfig.pceSecret),
                configSysId: configSysId,
                time_zone: gs.getSession().getTimeZoneName(),
                batch_size: gs.getProperty('x_illu2_illumio.bulk_operation_batch_size', 1000),
                enable_pce_mid_proxy: pceConfig.enable_pce_mid_proxy,
                retry_params: JSON.stringify(pceConfig.retry_params)
            };

            var eccQueue = new IllumioAddToECCQueue('IllumioUpdateWorkloads', pceConfig.midServer, parameters);
            var dispatched = eccQueue.insert();

            if (dispatched) {
                result.success = true;
                result.message = 'Deletion process started. ' + payload.deletionCount + ' workload(s) for deletion, ' + payload.unpairCount + ' for unpair. Track progress in Scheduled Jobs.';
            } else {
                scheduledJobGr.get(jobSysId);
                scheduledJobGr.job_status = 'failed';
                scheduledJobGr.job_completed = new GlideDateTime();
                scheduledJobGr.logs += '\n[' + new Date(new GlideDateTime().getNumericValue()).toISOString() + '] Failed to dispatch deletion to MID server';
                scheduledJobGr.update();
                result.message = 'Failed to dispatch deletion to MID server.';
            }
        } catch (ex) {
            gs.error('[IllumioDeletionHandler.deleteSelectedWorkloads] Exception: ' + ex);
            result.message = 'Error deleting workloads: ' + ex;
        }

        return JSON.stringify(result);
    },

    type: 'IllumioDeletionHandler'
});
